import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long a = scanner.nextLong();
        long b = scanner.nextLong();
        long max_iter = scanner.nextLong();
        int best_num = 0;
        int best_den = 1;
        for (int i = 1; i <= max_iter; i++) {
            long q = (a * i) / b;
            long diff1 = a * i - q * b;
            long diff2 = (q + 1) * b - a * i;
            if (diff1 > diff2) q++;
            if (Math.abs(best_den * (a * i - q * b)) < Math.abs(i * (a * best_den - b * best_num))) {
                best_num = (int) q;
                best_den = i;
            }
        }
        System.out.println(best_num + "/" + best_den);
        scanner.close();
    }
}
